let StaticFirstSeen = PrancerFindings
    | where DeviceProduct in ("sast", "sca") and isnotempty(CweId) and isnotempty(ConfigId) and iff('{Subscription}' != "", ResourceID contains '{Subscription}', true)
    | summarize StaticFirstSeen = min(TimeGenerated) by ConfigId, CweId;
let SwarmhackConfirmed = PrancerFindings
    | where DeviceProduct == "swarmhack" and isnotempty(CweId) and isnotempty(ConfigId) and iff('{Subscription}' != "", ResourceID contains '{Subscription}', true)
    | summarize SwarmhackConfirmed = min(TimeGenerated) by ConfigId, CweId;
let Gaps = StaticFirstSeen
    | join kind=inner SwarmhackConfirmed on ConfigId, CweId
    | extend DaysToWeaponize = datetime_diff("day", SwarmhackConfirmed, StaticFirstSeen)
    | where DaysToWeaponize >= 0;
let AvgMetric = Gaps | summarize Value = round(avg(DaysToWeaponize), 1) | extend Metric = "Avg Days to Weaponization";
let MaxMetric = Gaps | summarize Value = toreal(max(DaysToWeaponize)) | extend Metric = "Max Days to Weaponization";
union AvgMetric, MaxMetric
| project Metric, Value
